namespace ghidra.app.util.opinion;





using ghidra.app.util.bin;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util.exception;

/**
 * A {@link Loader} for processing Microsoft DEF files.
 */
public class DefLoader : AbstractProgramWrapperLoader {
	public static string DEF_NAME = "Module Definition (DEF)";

	public static readonly string NO_MAGIC = "0";

	private List<DefExportLine> parseExports(ByteProvider provider)
    {
		List<DefExportLine> list = new();
		using (InputStream inputStream = provider.getInputStream(0))
{
			bool hasExports = false;
			BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
			string line = null;
			while ((line = reader.readLine()) != null) {
				if (line.startsWith(";") || line.isEmpty()) {// comment
					continue;
				}
				else if (line.startsWith("LIBRARY")) {
					// why skip libraries?  Who knows?  If you do, please update this comment
				}
				else if (line.startsWith("EXPORTS")) {
					hasExports = true;
				}
				else if (hasExports) {
					DefExportLine exp = new DefExportLine(line);
					list.add(exp);
				}
			}
		}
		return list;
	}

	/* @Override */
	public Collection<LoadSpec> findSupportedLoadSpecs(ByteProvider provider)
    {
		List<LoadSpec> loadSpecs = new();

		string name = provider.getName();
		if (name != null && name.toLowerCase().endsWith(".def") &&
			!parseExports(provider).isEmpty()) {
			List<QueryResult> results = QueryOpinionService.query(getName(), NO_MAGIC, null);
			foreach (QueryResult result in results) {
				loadSpecs.add(new LoadSpec(this, 0, result));
			}
			if (loadSpecs.isEmpty()) {
				loadSpecs.add(new LoadSpec(this, 0, true));
			}
		}

		return loadSpecs;
	}

	/* @Override */
	public void load(Program prog, ImporterSettings settings)
    {

		if (!prog.getExecutableFormat().equals(PeLoader.PE_NAME)) {
			throw new IOException("Program must be a " + PeLoader.PE_NAME);
		}

		SymbolTable symtab = prog.getSymbolTable();
		Consumer<string> errorConsumer = err => settings.log().appendMsg("DefLoader", err);
		foreach (DefExportLine def in parseExports(settings.provider())) {
			Integer ordinal = def.getOrdinal();
			if (ordinal == null) {
				continue;
			}
			Symbol symbol = SymbolUtilities.getLabelOrFunctionSymbol(prog,
				SymbolUtilities.ORDINAL_PREFIX + ordinal, errorConsumer);
			if (symbol == null) {
				continue;
			}
			try {
				Symbol label =
					symtab.createLabel(symbol.getAddress(), def.getName(), SourceType.IMPORTED);
				label.setPrimary();
			}
			catch (InvalidInputException e) {
				settings.log().appendMsg(e.getMessage());
			}
		}
	}

	/* @Override */
	public string getName() {
		return DEF_NAME;
	}

	/* @Override */
	public bool supportsLoadIntoProgram(Program program) {
		return true;
	}
}
